const double kB = 1.380649e-23; // Boltzmann constant in J/K

// Generate random velocities from Maxwell-Boltzmann distribution
std::random_device rd;
std::mt19937 gen(rd());
std::normal_distribution<double> dist(0.0, 1.0);

for (size_t i = 0; i < velocities.size(); i++) {
    double sigma = std::sqrt(kB * temperature / masses[i]);
    velocities[i].x = sigma * dist(gen);
    velocities[i].y = sigma * dist(gen);
    velocities[i].z = sigma * dist(gen);
}

// Calculate and remove center of mass motion
double totalMass = 0.0;
vec3 totalMomentum(0.0, 0.0, 0.0);

for (size_t i = 0; i < velocities.size(); i++) {
    totalMass += masses[i];
    totalMomentum.x += masses[i] * velocities[i].x;
    totalMomentum.y += masses[i] * velocities[i].y;
    totalMomentum.z += masses[i] * velocities[i].z;
}

vec3 comVelocity(0.0, 0.0, 0.0);
if (totalMass > 0.0) {
    comVelocity.x = totalMomentum.x / totalMass;
    comVelocity.y = totalMomentum.y / totalMass;
    comVelocity.z = totalMomentum.z / totalMass;
}

for (size_t i = 0; i < velocities.size(); i++) {
    velocities[i].x -= comVelocity.x;
    velocities[i].y -= comVelocity.y;
    velocities[i].z -= comVelocity.z;
}
// END_CODE

